// Parse document upload request for customer_embeding table
const { documentId, customerId, widgetId, filename, fileUrl, fileType, fileContent } = $json;

// Validation
if (!documentId || !customerId || (!fileUrl && !fileContent)) {
  throw new Error('Missing required fields: documentId, customerId, and file source');
}

// Determine processing method
let textContent = '';
if (fileContent) {
  textContent = fileContent; // Direct text content
} else {
  // Will need to fetch from URL
  textContent = null;
}

return [{
  json: {
    documentId,
    customerId,
    widgetId: widgetId || null,
    filename,
    fileUrl: fileUrl || null,
    fileType: fileType || 'text/plain',
    textContent,
    needsFetch: !fileContent,
    startTime: Date.now()
  }
}];

// Extract text from fetched document
const documentData = $('Parse Document Request').item(0).json;
let textContent = '';

if (documentData.needsFetch) {
  // Get from HTTP request
  const fetchedData = $json;
  if (typeof fetchedData === 'string') {
    textContent = fetchedData;
  } else if (fetchedData.body) {
    textContent = fetchedData.body;
  } else {
    textContent = JSON.stringify(fetchedData);
  }
} else {
  // Use direct content
  textContent = documentData.textContent;
}

// Enhanced text cleaning for Turkish content
textContent = textContent
  .replace(/\s+/g, ' ')
  .replace(/[\x00-\x1F\x7F-\x9F]/g, '')
  // Fix Turkish character encoding issues
  .replace(/Ã§/g, 'ç')
  .replace(/Ä±/g, 'ı')
  .replace(/Å/g, 'ş')
  .replace(/Ã¼/g, 'ü')
  .replace(/Ã¶/g, 'ö')
  .replace(/Äÿ/g, 'ğ')
  .trim();

if (!textContent || textContent.length < 10) {
  throw new Error('Document is empty or too short');
}

return [{
  json: {
    ...documentData,
    textContent,
    textLength: textContent.length,
    wordCount: textContent.split(' ').length
  }
}];

// Enhanced chunking with Turkish language support
const { textContent, ...documentData } = $json;

const chunkSize = 1000;
const chunkOverlap = 200;
const chunks = [];

let currentPos = 0;
let chunkIndex = 0;

// Turkish sentence endings
const sentenceEndings = ['.', '!', '?', '…'];

while (currentPos < textContent.length) {
  const chunkEnd = Math.min(currentPos + chunkSize, textContent.length);

  // Find a good break point (end of sentence or word)
  let actualEnd = chunkEnd;
  if (chunkEnd < textContent.length) {
    // Look for sentence endings first
    for (let i = chunkEnd; i > currentPos + chunkSize * 0.5; i--) {
      if (sentenceEndings.includes(textContent[i]) && textContent[i + 1] === ' ') {
        actualEnd = i + 1;
        break;
      }
    }

    // If no sentence break, find word break
    if (actualEnd === chunkEnd) {
      for (let i = chunkEnd; i > currentPos + chunkSize * 0.7; i--) {
        if (textContent[i] === ' ') {
          actualEnd = i;
          break;
        }
      }
    }
  }

  const chunkContent = textContent.slice(currentPos, actualEnd).trim();

  if (chunkContent.length > 50) {
    chunks.push({
      chunkIndex,
      content: chunkContent,
      length: chunkContent.length,
      startPos: currentPos,
      endPos: actualEnd,
      wordCount: chunkContent.split(' ').length
    });
    chunkIndex++;
  }

  // Move to next chunk with overlap
  currentPos = Math.max(actualEnd - chunkOverlap, currentPos + 100);
  if (currentPos >= actualEnd) break;
}

return [{
  json: {
    ...documentData,
    chunks,
    chunkCount: chunks.length,
    processingStatus: 'chunked'
  }
}];

// Prepare embedding batch with context
const documentData = $('Intelligent Text Chunking').item(0).json;
const batchData = $json;

const currentBatch = documentData.chunks.slice(
  batchData.index * batchData.batchSize,
  (batchData.index + 1) * batchData.batchSize
);

// Prepare texts for embedding with context
const textsToEmbed = currentBatch.map(chunk => 
  `Belge: ${documentData.filename}\nİçerik: ${chunk.content}`
);

return [{
  json: {
    ...documentData,
    currentBatch,
    textsToEmbed,
    batchIndex: batchData.index,
    totalBatches: Math.ceil(documentData.chunks.length / batchData.batchSize)
  }
}];

// Process embeddings for customer_embeding table
const embeddingResponse = $json;
const batchData = $('Prepare Embedding Batch').item(0).json;

if (!embeddingResponse.data || !Array.isArray(embeddingResponse.data)) {
  throw new Error('Invalid embedding response from OpenAI');
}

const embeddings = batchData.currentBatch.map((chunk, index) => {
  const embedding = embeddingResponse.data[index];

  return {
    id: `${batchData.documentId}_chunk_${chunk.chunkIndex}`,
    kind: 'document',
    question: null,
    answer: null,
    text: chunk.content,
    chunk_index: chunk.chunkIndex,
    chunk_total: batchData.chunkCount,
    metadata: {
      documentId: batchData.documentId,
      filename: batchData.filename,
      fileType: batchData.fileType,
      chunkLength: chunk.length,
      wordCount: chunk.wordCount,
      startPos: chunk.startPos,
      endPos: chunk.endPos,
      widgetId: batchData.widgetId,
      processingVersion: '2.0',
      language: 'tr'
    },
    embedding: `[${embedding.embedding.join(',')}]`,
    embedding_model: 'text-embedding-ada-002',
    embedding_dim: embedding.embedding.length,
    customer_id: batchData.customerId,
    created_at: new Date().toISOString()
  };
});

return [{
  json: {
    embeddings,
    documentId: batchData.documentId,
    batchIndex: batchData.batchIndex,
    totalBatches: batchData.totalBatches,
    tokensUsed: embeddingResponse.usage?.total_tokens || 0
  }
}];
